const e={ocnal:{baipishu:"백서",home1:"디지털 통화의 세계를 열어보세요",home2:"지금 입금하기",home3:"이름",home4:"가격",home5:"24시간 변동률",home6:"거래",home7:"시작하기",home8:"계정 만들기",home9:"더 많은 혜택과 서비스를 이용하려면 계정을 등록하세요",home10:"가입하기",home11:"자금 입금",home12:"계정에 자금을 추가하고 암호화폐 투자를 시작하세요",home13:"암호화폐 입금",home14:"거래 시작",home15:"매도, 매수 또는 거래 복사로 더 많은 기회를 발견하세요",home16:"시장 탐색",home17:"암호화폐 시장은 급성장 중이며, 디지털 자산과 블록체인 기술을 포함합니다. 전망은 밝지만 투자에는 신중해야 합니다.",home18:"현물",home19:"가격 변동이 빠른 실시간 현물 거래.",home20:"영구 계약",home21:"계약 거래는 레버리지를 제공하여 높은 수익을 얻을 수 있습니다.",home22:"옵션",home23:"옵션 거래는 유연한 헤징 전략을 통해 리스크를 관리하고 수익을 얻을 수 있습니다.",home24:"AI 재테크",home25:"자신 있게 계획하고, 현명하게 투자하고, 걱정을 줄이세요",home26:"역대 최고 연 환산 수익률",home27:"자유형",home28:"정기형",home29:"지금 구매",home30:"누구나 디지털 화폐를 사용할 수 있습니다",home31:"암호화폐 거래의 첫 경험부터 금융 상품 첫 구매까지, 플랫폼이 손쉽게 코인을 벌 수 있도록 도와드립니다.",home32:"암호화폐 배우기",home33:"암호화폐를 배우고 투자 여정을 시작하세요",home34:"자주 묻는 질문",home35:"암호화폐 여정을 시작할 준비가 되셨나요?",home36:"암호화폐 거래소란?",home37:"암호화폐 거래소는 비트코인, 이더리움, 테더 등 암호화폐를 사고팔 수 있는 디지털 시장입니다. 바이낸스는 거래량 기준 세계 최대 거래소입니다.",home38:"플랫폼은 어떤 상품을 제공하나요?",home39:"세계 선도 암호화폐 거래 플랫폼으로서, 현재 180개국 이상에서 1억 5천만 명 이상의 사용자를 보유하고 있습니다. 낮은 수수료로 350개 이상의 암호화폐를 거래할 수 있습니다.<br><br>사용자는 다음을 수행할 수 있습니다:<br><br>1. 수백 개의 코인 및 거래쌍 거래<br><br>2. 현물 거래로 암호화폐 매매<br><br>3. 자산 관리 상품을 통해 이자 수익 얻기",home40:"플랫폼에서 암호화폐 거래하는 방법",home41:"플랫폼에서는 현물, 선물, 옵션 시장에서 다양한 암호화폐를 거래할 수 있습니다. 계정을 등록하고, 신원 인증 후 자금을 입금하면 거래를 시작할 수 있습니다.",home42:"이 플랫폼은 안전한가요?",home43:"플랫폼은 안전하고 신뢰할 수 있는 거래 환경을 제공합니다. 세계 최고 수준의 보안 기술과 전문 팀이 자산을 보호합니다. 모든 사용자 자산은 1:1로 완전히 보장됩니다.",home44:"비밀번호를 잊어버렸을 때는?",home45:"로그인 페이지에서 ‘비밀번호 찾기’를 클릭하여 재설정하세요.",home46:"신원 인증이 필요한 이유는?",home47:"자금 보호 및 자금세탁 방지를 위해, 수신 계정이 본인 정보와 일치해야 합니다.",home48:"시장",home49:"글로벌 암호화폐 거래 시장은 다중 통화 거래를 지원하며, 안전성과 효율성을 모두 제공합니다.",home50:"내 계정",home51:"입금",home52:"출금",home53:"전환",home54:"인기",home55:"새로 발행된 토큰에 투자하여 높은 수익 가능성을 확보하세요",home56:"뉴스",home57:"왜 우리를 선택해야 하나요?",home58:"수백만 명이 신뢰합니다",home59:"사용자 수",home60:"협력 단위",home61:"최소 거래 수수료",home62:"파트너",home63:"24시간 거래량",home64:"디지털 자산의 새 시대를 열다",home65:"안전하게 거래, 쉽게 투자",home66:"지금 시작하기",home67:"스마트 거래, 미래와 연결",home68:"초고속 거래, 기회를 놓치지 마세요",home69:"디지털 자산, 손끝에 닿다",jianguanzhengshu:"규제 증명서",falvzhengmingshu:"법적 증명서",withdrawNote:"출금 안내:<br><br>출금 처리 시간은 24시간입니다<br><br>출금 신청을 제출하면 출금이 진행 중이므로 자산이 일시 동결되며 시스템에서 임시 보관합니다. 이는 자산이 손실되었거나 이상이 있음을 의미하지 않습니다.<br><br>토큰 출금 신청은 제출 후 12시간 이내에 입금됩니다. 예상 입금 시간 이후에도 입금되지 않으면 온라인 고객 센터에 문의하세요.<br><br>대액 출금은 VIP 회원만 이용할 수 있습니다. 자세한 내용은 온라인 고객 센터에 문의하세요."},yingshe:{miaoheyue:"옵션 거래",miaoheyuejiaoyi:"옵션 거래",heyuezhanghu:"거래 계좌"},deltax:{company_bylaws:"회사 정관",good_standing_certificate:"양호 증명서",about_title:"회사 소개",about_text_1:"당사는 영국, 유럽, 호주에 사무소를 두고 유럽에서 가장 빠르게 성장하는 거래 플랫폼 중 하나입니다. 우리는 직관적인 기술, 심층 교육, 그리고 전폭적인 지원을 통해 고객의 거래를 촉진하며, 모든 의사결정의 중심에 고객을 둡니다.",about_text_2:"우리의 사명은 트레이더가 자신감 있게 거래하고 더 나은 결정을 내릴 수 있도록 필요한 도구와 리소스를 제공하는 것입니다. 이 사명 덕분에 우리는 업계를 선도하는 권위 기관으로부터 여러 상을 받았습니다.",stats_title:"성장 개요",stat_global_label:"글로벌 운영",stat_global_desc:"전 세계 사무소 수가 계속 늘어나면서 183개 국가/지역의 고객에게 서비스를 제공할 수 있어 자랑스럽게 생각합니다",stat_global_link:"거래에 대해 알아보기",stat_traders_label:"트레이더",stat_traders_desc:"출시 이후 우리 글로벌 트레이더 커뮤니티의 거래량은 530억 달러를 초과했습니다",stat_traders_link:"최신 뉴스 보기",stat_support_label:"지원 직원",stat_support_desc:"우리의 친절한 고객 서비스 팀은 12개 언어로 24시간 연중무휴로 계좌 관련 모든 문제를 도와드립니다",stat_support_link:"지원",promise_title:"고객에 대한 우리의 약속",promise_desc:"거래는 진정으로 마스터하는 사람이 드문 기술입니다. 하지만 혁신적인 기술, 몰입형 교육, 그리고 거래 행동에 대한 독창적인 통찰을 올바르게 결합하면 누구나 시장에서 거래 전문성을 키울 수 있다고 믿습니다. 경험 많은 트레이더이든 이제 시작하는 초보자이든, 지식과 기술을 향상시키는 데 필요한 도구를 제공합니다.",promise_customer_name:"고객 우선",promise_customer_text:"트레이더에 의해 만들어진 우리는 전문 연구, 데이터 과학, 그리고 독창적인 통찰을 적용하여 고객이 성장할 수 있도록 영감을 주는 제품을 개발합니다",promise_innovation_name:"끊임없는 발전",promise_innovation_text:"우리는 끊임없이 플랫폼을 최적화하여 원활한 사용자 경험을 제공하고, 혁신적이고 기술 중심인 도구를 통해 자신감 있는 거래와 더 나은 결정을 가능하게 하기 위해 노력합니다",promise_transparency_name:"투명성",promise_transparency_text:"우리는 업계에서 가장 경쟁력 있는 가격 책정과 사용하기 쉬우면서도 풍부한 교육 리소스를 제공하여 거래 장벽을 허물기 위해 노력합니다",promise_expertise_name:"전문성",promise_expertise_text:"우리의 국제 팀은 수십 년의 거래 기술과 전문 지식을 보유하여 사용자 친화적이고 기술 중심이며 직관적인 플랫폼의 기반을 마련했습니다",expertise_title:"우리의 전문성",expertise_text_1:"수상 경력이 있는 브로커로서, 우리는 기술 중심의 직관적인 사용자 경험, 고품질 고객 지원, 그리고 뛰어난 가치를 인정받고 있습니다. 기술은 우리가 하는 모든 것의 핵심이며, 실시간 시장 데이터, 고급 차트 도구, 모바일 거래를 지원하는 반응형 모바일 앱 등 스마트한 기능을 제공합니다. 우리의 목표는 개인 투자자가 전 세계 금융 상품에 원활하게 접근할 수 있도록 하는 것입니다.",expertise_text_2:"우리는 고객이 자신감 있게 거래하고 더 현명한 결정을 내릴 수 있도록 돕는 새로운 방법을 끊임없이 모색하며, 끊임없이 변화하는 거래 환경에서 최신 기술, 심층 교육 리소스, 경쟁력 있는 가격을 제공합니다.",expertise_stat_traders:"트레이더",expertise_stat_service:"고객 서비스",expertise_stat_unit_second:"초",expertise_stat_speed_label:"평균 실행 속도",expertise_stat_indicators:"기술적 지표",expertise_footnote:"2022년 우리 내부 서버 데이터 기준",awards_title:"업계의 평가",awards_desc_1:"우리의 직관적인 제품, 헌신적인 고객 서비스, 그리고 지속적인 혁신은 업계를 선도하는 권위 기관으로부터 여러 차례 인정받았습니다.",awards_desc_2:"2023년 Deloitte Technology Fast 50은 우리를 중동과 키프로스에서 가장 빠르게 성장하는 50대 기술 기업 중 하나로 선정했습니다. 다음은 최근 수상 내역의 일부입니다:",products_title:"우리의 제품과 서비스",product_cfd_name:"CFD 거래",product_cfd_desc:"외환, 지수, 주식, 상품 등을 롱/숏으로 거래하며, 고정 만기일이 없고 영국 주식에는 스탬프 듀티가 없습니다",product_platform_name:"사용자 친화적 플랫폼",product_platform_desc:"우리는 데스크톱, 모바일, API를 통해 고객의 편의성을 최우선으로 거래할 수 있도록 합니다",product_demo_name:"데모 거래 계좌",product_demo_desc:"트레이더는 가상 자금을 사용하여 리스크 없이 우리 플랫폼을 체험하고 거래 전략을 최적화할 수 있습니다",product_education_name:"교육",product_education_desc:"최신 기본적 및 기술적 시장 동인에 대한 심층 통찰을 제공하여 트레이더가 정보에 기반한 결정을 내릴 수 있도록 돕습니다",product_more:"더 보기",products_footnote:"세금 처리는 개인 상황에 따라 다르며 영국 이외의 관할권에서는 변경되거나 다를 수 있습니다",global_title:"글로벌 사무소",award_source_good_money:"Good Money Guide",award_source_online_money:"Online Money Awards",award_source_forexbrokers:"ForexBrokers.com",award_source_investment_trends:"Investment Trends",award_source_advfn:"ADVFN",award_source_ft:"Financial Times Investors’ Chronicle",award_good_money_guide:"2023년 최고의 거래 앱",award_online_money:"2023년 최고의 CFD 제공업체",award_forexbrokers:"2023년 가장 빠르게 성장하는 브로커",award_investment_satisfaction:"2022년 전반적인 고객 만족도",award_investment_value:"2022년 가성비 상",award_advfn:"2023년 가장 빠르게 성장하는 브로커",award_ft_investors:"2022년 신규 투자자 지원"},licai:{zhiyawakuang:"스마트 수익",zhiyawakuangjiaoyi:"스마트 수익 거래"}};export{e as default};
